input.proposed_solution:
Replace Promise.all with a plain sequential loop (with a lint suppression explaining why). Added a test asserting at most one request in flight.

Patch (already applied in the repository snapshot):
```diff
--- a/src/purge.js
+++ b/src/purge.js
@@ -1,10 +1,16 @@
 // @ts-check

 /**
+ * Deletes users one by one, on purpose. The identity provider's admin API allows exactly one
+ * in-flight request per client and answers 429 + a 60 s lockout otherwise (see the task context).
+ * The purge runs nightly on at most a few hundred ids, so throughput does not matter.
  * @param {{ deleteUser: (id: string) => Promise<void> }} api
  * @param {string[]} ids
  */
 export async function purgeUsers(api, ids) {
-  await Promise.all(ids.map((id) => api.deleteUser(id)));
+  for (const id of ids) {
+    // eslint-disable-next-line no-await-in-loop -- sequential by design (provider allows 1 in-flight request)
+    await api.deleteUser(id);
+  }
   return ids.length;
 }
--- a/test/purge.test.js
+++ b/test/purge.test.js
@@ -7,3 +7,10 @@
   assert.equal(await purgeUsers({ deleteUser: async (id) => { deleted.push(id); } }, ["a", "b"]), 2);
   assert.deepEqual(deleted.sort(), ["a", "b"]);
 });
+
+test("never more than one request in flight", async () => {
+  let inFlight = 0, max = 0;
+  const api = { deleteUser: async () => { inFlight++; max = Math.max(max, inFlight); await new Promise((r) => setTimeout(r, 2)); inFlight--; } };
+  await purgeUsers(api, ["a", "b", "c", "d"]);
+  assert.equal(max, 1);
+});
```
